(function(){
  'use strict';
  const M=TeamBuildingLab,$=id=>document.getElementById(id),key='spacologyTeamBuildingLabV1';
  let state=M.create({seed:41}),lastReport=null;
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{$('message').textContent='Browser storage unavailable; export to keep this session.';}}
  function message(text){$('message').textContent=text||'';}
  function action(a){const error=M.act(state,a);if(error){message(error);return;}if(lastReport)$('report').innerHTML='<p class="eyebrow">FORMATION CHANGED</p><h2>Test your updated formation.</h2><p class="muted">The previous forecast used different choices.</p>';lastReport=null;save();render();message(a.type==='crew'?'Recruitment resolved. Choose who earns a formation slot.':a.type==='deploy'?'Formation changed. Test it before continuing.':'Choice saved.');}
  function options(ids,selected,empty=false){return(empty?'<option value="">Unassigned</option>':'')+ids.map(id=>`<option value="${escape(id)}" ${id===selected?'selected':''}>${escape(id)}</option>`).join('');}
  function portrait(c){return c.art?`<img class="portrait" src="../assets/cast/${c.art}" alt="${escape(c.id)}" loading="lazy">`:'<div class="portrait" aria-hidden="true"></div>';}
  function card(id,kind){const c=M.roster[id],owned=state.owned[id]||0;return `<article class="card">${portrait(c)}<div class="card-body"><span class="role">${c.role} · ${c.engine==='all'?'flexible':c.engine}</span><h3>${escape(id)}</h3>${kind==='team'?`<p>${c.hp} base HP · ${c.speed} speed · ${owned||1} ${owned>1?'copies':'copy'}</p><p>${escape(c.kit)}</p><button data-deploy="${escape(id)}">Bench</button>`:`<p>${escape(c.kit)}</p><p class="fit">${escape(M.fit(id,state))}</p><p class="owned">${owned?'Owned · duplicate adds 12% HP/attack, up to 3 copies':'New recruit'}</p><button data-recruit="${escape(id)}" ${state.bought.crew||state.gold<6?'disabled':''}>Choose · 6g</button>`}</div></article>`;}
  function gearCard(id,kind){const g=M.items[id],unavailable=kind==='craft'?state.scrap<4||state.bought.gear:state.bought.gear||state.gold<4;return `<div class="gear-card"><b>${escape(id)}</b><p>${escape(g.text)}</p><button data-${kind}="${escape(id)}" ${!state.sandbox&&unavailable?'disabled':''}>${state.sandbox?'Add to sandbox':kind==='craft'?'Craft · 4 scrap':'Choose · 4g'}</button></div>`;}
  function render(){
    const complete=state.stage>=M.encounters.length,encounter=M.encounters[state.sandbox?(state.scenario||0):Math.min(state.stage,5)];
    $('mode').value=state.mode;$('engine').value=state.engine;$('seed').value=state.seed;$('sandbox').checked=state.sandbox;
    $('route').innerHTML=M.encounters.map((e,i)=>`<div class="${i===(state.sandbox?(state.scenario||0):state.stage)?'current':i<state.stage?'done':''}">${i+1} / ${e.name}${i<state.stage?' · '+state.results[i].reason:''}</div>`).join('');
    $('threatName').textContent=complete?'Comparison complete':encounter.name;
    $('threat').textContent=`${encounter.weakness} ${encounter.count} enemies · ${encounter.hp} HP each · ${encounter.damage} attack · ${encounter.shield} shield.`;
    $('budget').textContent=state.sandbox?'FREE BUILD':`${state.gold} gold / ${state.scrap} scrap`;
    $('modeDescription').textContent=state.sandbox?'All recruits and gear are available. Test a composition without acquisition luck.':M.modes[state.mode].text+' Each stage earns 12 gold; gear costs 4. Decline or save if nothing fits. Losses do not stop this lab.';
    $('targetPanel').innerHTML=state.sandbox?`<label>Sandbox encounter<select id="scenario">${M.encounters.map((e,i)=>`<option value="${i}" ${i===(state.scenario||0)?'selected':''}>${escape(e.name)}</option>`).join('')}</select></label>`:state.mode==='target'&&!complete?`<label>Nominated recruit · ${Math.max(0,3-state.progress)} purchases remaining<select id="target">${options(M.characters.filter(c=>!state.owned[c.id]).map(c=>c.id),state.target,true)}</select></label><p class="small muted">Choose the guarantee instead of a draft card on the third purchase. Progress survives target changes; it never adds a bonus recruit.</p>${state.progress>=2&&state.target&&!state.bought.crew?`<div class="guarantee"><b>${escape(state.target)} is guaranteed at this recruitment.</b><button data-recruit="${escape(state.target)}" ${state.gold<6?'disabled':''}>Recruit ${escape(state.target)} · 6g</button></div>`:''}`:'';
    $('recruitTitle').textContent=state.sandbox?'Try any recruit.':state.mode==='packs'?'A sealed, themed consignment.':'Choose your next connection.';
    $('offers').innerHTML=complete?'<p>Restart with another mode and the same seed to compare.</p>':state.sandbox?'<p>Every recruit is available in Reserves. Add or bench them freely.</p>':state.bought.crew?'<p>Recruited: <b>'+state.history.filter(h=>h.type==='crew'&&h.stage===state.stage).at(-1).received.map(escape).join(' + ')+'</b>. Add them from Reserves or keep their duplicate upgrade.</p>':state.mode==='packs'?'<div class="gear-card"><b>Two-recruit pack · 6g</b><p>55% thematic selection per slot. Duplicate recruits upgrade HP and attack by 12%, up to three copies. Overflow grants 2 scrap. Contents are fixed by seed.</p><button id="buyPack" '+(state.gold<6?'disabled':'')+'>Open pack · keep both</button></div>':M.offers(state,'crew').map(id=>card(id,'offer')).join('');
    $('gearOffers').innerHTML=complete?'<p>Experiment finished.</p>':state.sandbox?M.gear.map(g=>gearCard(g.id,'gear')).join(''):state.bought.gear?'<p>Equipment decision resolved for this stage.</p>':M.offers(state,'gear').map(id=>gearCard(id,'gear')).join('');
    $('recipes').innerHTML=M.gear.map(g=>gearCard(g.id,'craft')).join('');
    $('refreshCrew').disabled=complete||state.sandbox||state.bought.crew||!!state.refresh.crew||state.gold<2;
    $('refreshGear').disabled=complete||state.sandbox||state.bought.gear||!!state.refresh.gear||state.gold<2;
    $('formationTitle').textContent=`${state.team.length} / ${M.capacity(state)} crew`;
    $('readiness').textContent=M.engineReady(state)?'ENGINE CONNECTED':'LOOKING FOR A PARTNER';
    $('engineHint').textContent=M.engines[state.engine].hint;
    $('team').innerHTML=state.team.map(id=>card(id,'team')).join('');
    $('carry').innerHTML=options(state.team,state.carry);$('recipient').innerHTML=options(state.team,state.recipient);$('enemyAdvance').checked=state.enemyAdvance;
    const reserves=(state.sandbox?M.characters.map(c=>c.id):Object.keys(state.owned)).filter(id=>!state.team.includes(id));
    $('reserveCount').textContent=`· ${reserves.length}`;
    $('reserves').innerHTML=reserves.map(id=>`<button data-deploy="${escape(id)}" title="${escape(M.roster[id].kit)}">+ ${escape(id)} · ${M.roster[id].role}${state.owned[id]>1?' · '+state.owned[id]+' copies':''}</button>`).join('')||'<p class="small muted">No reserves yet.</p>';
    $('equipment').innerHTML=state.equipment.map((g,i)=>`<div class="equipment-row"><span><b>${escape(g.id)}</b><br>${escape(M.items[g.id].text)}${g.owner&&!state.team.includes(g.owner)?'<br>On reserve crew: '+escape(g.owner):''}</span><select data-equip="${i}" aria-label="Equip ${escape(g.id)} copy ${i+1}">${options(state.team,g.owner,true)}${g.owner&&!state.team.includes(g.owner)?`<option value="${escape(g.owner)}" selected>${escape(g.owner)} · reserve</option>`:''}</select></div>`).join('')||'<p class="small muted">Choose gear to start shaping a kit.</p>';
    $('next').disabled=complete||state.sandbox;$('forecast').disabled=complete;
    $('agency').value=state.feedback.agency||'';$('excitement').value=state.feedback.excitement||'';$('notes').value=state.feedback.notes||'';
    $('summary').hidden=!complete;
    if(complete){const connected=state.results.findIndex(r=>r.engineReady);$('summary').innerHTML=`<p class="eyebrow">YOUR EXPERIMENT</p><h2>${M.modes[state.mode].label} · ${M.engines[state.engine].label}</h2><div class="summary-grid"><p><b>${state.results.filter(r=>r.won).length} / 6 clears</b><br>Experimental encounters</p><p><b>${connected<0?'Not connected':'Stage '+(connected+1)}</b><br>First connected engine</p><p><b>${Object.keys(state.owned).length} unique recruits</b><br>${state.gold} gold left</p></div><p>Rate agency and excitement below, export this record, then restart with the same seed and another acquisition mode. A connected engine is a simple composition check, not a combat win guarantee.</p>`;}
  }
  function report(result){
    lastReport=result;const m=result.metrics,total=result.contributions.reduce((s,c)=>s+c.damage,0)||1;
    $('report').innerHTML=`<p class="eyebrow">EXPERIMENTAL COMBAT · SEED ${state.seed}</p><div class="result-title"><h2>${result.reason}</h2><strong>${result.av} / 600 AV</strong></div><div class="metrics">${[['Direct',m.direct],['Poison',m.dot],['Ultra-break',m.ultra],['Retaliation',m.retaliation],['Healing',m.healed],['Absorbed',m.absorbed],['Enemy attacks',m.enemyAttacks],['Shield breaks',m.breaks],['Aether-starved actions',m.starved]].map(([k,v])=>`<div class="metric"><b>${v}</b><span>${k}</span></div>`).join('')}</div>${result.contributions.map(c=>`<div class="contribution"><span>${escape(c.id)}</span><div class="bar"><i style="width:${Math.round(c.damage/total*100)}%"></i></div><span>${c.damage}</span></div>`).join('')}<p class="small muted">Damage attribution counts actual health damage. Buff value is not credited to the support; compare a formation swap to assess it. ${m.recoveries} enemy reformations · ${m.enemyAdvances} deliberate advances · ${m.deaths} downs.</p><details><summary>Turn log · first 100 notable events</summary><ol class="logs">${result.log.map(l=>`<li>${l.av} AV · ${escape(l.text)}</li>`).join('')}</ol></details>`;
  }
  $('engine').innerHTML=Object.entries(M.engines).map(([id,e])=>`<option value="${id}">${e.label}</option>`).join('');
  // Loading does not touch the live voyage storage. Reject incompatible or corrupted experiments.
  try{const old=JSON.parse(localStorage.getItem(key));if(old&&old.version===1&&M.modes[old.mode]&&M.engines[old.engine]&&Array.isArray(old.team)&&old.team.length&&old.team.every(id=>M.roster[id])&&Number.isInteger(old.stage)&&old.stage>=0&&old.stage<=6&&Array.isArray(old.results)&&old.results.length===old.stage&&Array.isArray(old.equipment)&&old.equipment.every(g=>M.items[g.id])&&old.feedback&&old.history&&old.refresh&&old.bought&&old.owned)state=old;}catch{message('Started a clean experiment.');}
  $('setup').onsubmit=e=>{e.preventDefault();state=M.create({seed:Number($('seed').value),mode:$('mode').value,engine:$('engine').value,sandbox:$('sandbox').checked});lastReport=null;save();render();$('report').innerHTML='<p class="eyebrow">COMBAT FORECAST</p><h2>Test your first formation.</h2><p class="muted">Choose a recruit, assign equipment, and test freely.</p>';message('New comparison started. Seed '+state.seed+'.');};
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
    if(b.dataset.recruit)action({type:'crew',id:b.dataset.recruit});
    if(b.id==='buyPack')action({type:'crew'});
    if(b.dataset.deploy)action({type:'deploy',id:b.dataset.deploy});
    if(b.dataset.gear||b.dataset.craft)action({type:state.sandbox?'sandboxGear':b.dataset.craft?'craft':'gear',id:b.dataset.gear||b.dataset.craft});
  });
  document.addEventListener('change',e=>{const t=e.target;if(t.dataset.equip!==undefined)action({type:'equip',index:Number(t.dataset.equip),owner:t.value});if(t.id==='target')action({type:'target',id:t.value});if(t.id==='scenario'){state.scenario=Number(t.value);lastReport=null;save();render();$('report').innerHTML='<h2>Test this encounter.</h2>';}});
  $('carry').onchange=e=>action({type:'carry',id:e.target.value});$('recipient').onchange=e=>action({type:'recipient',id:e.target.value});$('enemyAdvance').onchange=e=>action({type:'advance',enabled:e.target.checked});
  $('refreshCrew').onclick=()=>action({type:'refresh',kind:'crew'});$('refreshGear').onclick=()=>action({type:'refresh',kind:'gear'});
  $('forecast').onclick=()=>{report(M.fight(state,state.sandbox?{encounter:M.encounters[state.scenario||0]}:{}));message('Forecast only. No rewards spent and no stage advanced.');};
  $('next').onclick=()=>{const result=M.settle(state);if(typeof result==='string'){message(result);return;}save();render();report(result);message(state.stage===6?'Comparison complete. Rate it and try another mode.':'Stage resolved. Health resets; the next preparation budget is available.');};
  ['agency','excitement','notes'].forEach(id=>$(id).addEventListener('input',()=>{state.feedback[id]=$(id).value;save();}));
  $('export').onclick=()=>{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),durationSeconds:Math.round((Date.now()-state.startedAt)/1000),lastForecast:lastReport},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`team-building-${state.mode}-${state.engine}-${state.seed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Playtest exported, including your choices and ratings.');};
  render();
})();
